import{_ as s,C as r,o as t,c as i,a3 as a,b as d,w as o,a as c,E as l,a4 as p}from"./chunks/framework.DNWyyI0w.js";const _=JSON.parse('{"title":"Delegation","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/delegation.md","filePath":"concepts/delegation.md"}'),h={name:"concepts/delegation.md"};function g(u,e,m,k,f,C){const n=r("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a(`<h1 id="delegation" tabindex="-1">Delegation <a class="header-anchor" href="#delegation" aria-label="Permalink to &quot;Delegation&quot;">​</a></h1><p>Delegation is how work leaves PRIME and reaches something that can do it. It is implemented as an MCP server built per WebSocket connection — one toolbelt, scoped to the connected operator.</p><h2 id="the-core-three" tabindex="-1">The core three <a class="header-anchor" href="#the-core-three" aria-label="Permalink to &quot;The core three&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>delegate_to_project(project, mode, task)  → a repo-scoped project agent</span></span>
<span class="line"><span>run_agent(agent, task)                    → a custom agent (incl. department leads)</span></span>
<span class="line"><span>remember(facts)                           → semantically update memory</span></span></code></pre></div><p>Everything else on the belt is management: run control, projects, agents, crons, reflexes, activity search.</p><h2 id="routing" tabindex="-1">Routing <a class="header-anchor" href="#routing" aria-label="Permalink to &quot;Routing&quot;">​</a></h2>`,6)),(t(),d(p,null,{default:o(()=>[l(n,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20P%5B%22PRIME%22%5D%20--%3E%7Cdelegate_to_project%7C%20Q%7B%22mode%3F%22%7D%0A%20%20%20%20Q%20--%3E%7Cask%7C%20A%5B%22Project%20agent%20%E2%80%94%20read-only%5CnRead%2C%20Grep%2C%20Glob%22%5D%0A%20%20%20%20Q%20--%3E%7Cwork%7C%20B%5B%22Project%20agent%20%E2%80%94%20write%5Cnedits%2C%20commits%2C%20opens%20PR%22%5D%0A%20%20%20%20P%20--%3E%7Crun_agent%7C%20C%7B%22target%20is%20a%5Cndepartment%20lead%3F%22%7D%0A%20%20%20%20C%20--%3E%7Cno%7C%20D%5B%22Custom%20agent%5Cnspecialist%2C%20does%20the%20work%22%5D%0A%20%20%20%20C%20--%3E%7Cyes%7C%20E%5B%22Department%20lead%5Cngets%20its%20own%20delegate_to_project%5Cn%2B%20delegate_to_specialist(s)%22%5D%0A%20%20%20%20E%20--%3E%7Cfans%20out%20below%20it%7C%20A%0A%20%20%20%20E%20--%3E%7Cfans%20out%20below%20it%7C%20D%0A%20%20%20%20B%20-.-%3E%7Capproval%3A%20confirm%7C%20F%5B%22Run%20parks%20at%20awaiting_input%5CnPendingApproval%22%5D%0A%20%20%20%20F%20--%3E%7Capproved%3A%20true%7C%20B%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="delegate-to-project" tabindex="-1"><code>delegate_to_project</code> <a class="header-anchor" href="#delegate-to-project" aria-label="Permalink to &quot;`delegate_to_project`&quot;">​</a></h2><p>Takes a registry project name, a <code>mode</code>, and the task.</p><ul><li><strong><code>mode: &#39;ask&#39;</code></strong> — read-only. The agent gets <code>Read</code>, <code>Grep</code>, <code>Glob</code> and nothing else.</li><li><strong><code>mode: &#39;work&#39;</code></strong> — the agent may write, commit, and open a PR.</li></ul><p>Before it runs, the engine:</p><ol><li>Resolves the project and reads its policy (<code>branch</code>, <code>approval</code>, <code>verify</code>).</li><li>Takes a <strong>repo lock</strong> — two delegations never touch the same checkout concurrently. Custom agents take an equivalent agent lock.</li><li>Checks the operator&#39;s permissions and spend allowance.</li><li>Resumes the participant&#39;s existing provider session, if the cwd, mode, and sandbox all match — a mismatch must not resume.</li></ol><p>If the policy says <code>approval: confirm</code>, a <code>work</code> delegation does not run. It parks the Run at <code>awaiting_input</code> holding a structured <code>PendingApproval</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ id, taskId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, target, task, mode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;work&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, question, createdAt }</span></span></code></pre></div><p>Structured, not a free-text &quot;yes&quot; guess — so the UI can render Approve/Deny for the precise change, and approving maps directly to re-running <em>that</em> delegation with <code>approved: true</code>.</p><h2 id="run-agent" tabindex="-1"><code>run_agent</code> <a class="header-anchor" href="#run-agent" aria-label="Permalink to &quot;`run_agent`&quot;">​</a></h2><p>Runs a custom agent. If the target is a <strong>department lead</strong>, the spawn is different: the lead is handed its own delegation tools scoped to its department (see <a href="./agents-and-departments">Agents &amp; Departments</a>), so the work continues to fan out below it.</p><p>Custom agents get a <strong>per-run workspace</strong> (<code>RunParticipant.workDir</code>), so two concurrent runs using the same agent never share a directory.</p><h2 id="batched-delegation" tabindex="-1">Batched delegation <a class="header-anchor" href="#batched-delegation" aria-label="Permalink to &quot;Batched delegation&quot;">​</a></h2><p>In guided mode the engine batches independent ready tasks — tasks whose <code>dependsOn</code> are all satisfied — and dispatches them together. Results are clipped against a shared context budget (<code>BATCH_RESULT_FLOOR</code> guarantees each result a minimum), so one verbose agent cannot starve the others out of the context window.</p><h2 id="the-report-contract" tabindex="-1">The report contract <a class="header-anchor" href="#the-report-contract" aria-label="Permalink to &quot;The report contract&quot;">​</a></h2><p>Every delegated agent is given a report contract: its final message is a <strong>handover</strong>, not a transcript. Verdict first, one line per thing asked, every claim carrying its own proof inline — a <code>file:line</code>, a command and its exit code, a count. No file dumps, no narration. The length of each report is recorded (<code>RunUsageEntry.reportChars</code>) <em>before</em> clipping, so whether the contract actually shortens reports is a measurable question rather than an assumed one.</p><h2 id="what-a-delegation-costs" tabindex="-1">What a delegation costs <a class="header-anchor" href="#what-a-delegation-costs" aria-label="Permalink to &quot;What a delegation costs&quot;">​</a></h2><p>Each settled delegation appends a <code>RunUsageEntry</code>: the actor, every model it touched (the one it actually ran on first), fresh input tokens, cache reads, cache creation, output tokens, cost, and duration. Calls the provider never priced are flagged <code>unpriced</code> — &quot;unpriced&quot; is never silently rendered as &quot;free&quot;.</p><h2 id="loop-guards" tabindex="-1">Loop guards <a class="header-anchor" href="#loop-guards" aria-label="Permalink to &quot;Loop guards&quot;">​</a></h2><ul><li><strong>Repo/agent locks</strong> serialise access to a checkout or an agent directory.</li><li><strong>Attempt budgets</strong> cap retries globally and per task (<code>attemptBudget</code>, which cannot exceed the global setting).</li><li><strong>Spend enforcement</strong> blocks a delegation when the operator&#39;s allowance is exhausted, and can clamp the effort tier rather than refusing outright.</li><li><strong>Chain depth</strong> on emitted events is capped by the bus, so reflex-triggered runs cannot recurse forever.</li></ul><p>See also: <a href="/docs/reference/orchestrator-tools">Orchestrator Tools</a> · <a href="/docs/guides/guardrails">Guardrails</a></p>',20))])}const v=s(h,[["render",g]]);export{_ as __pageData,v as default};
